{
  "example": {
    "content": {
      "beats": [
        {
          "role": "a-roll",
          "subtitle": "Video editor, small teams",
          "text": "Rina Halim"
        },
        {
          "at_cue": 2,
          "key": "Pauses captions",
          "role": "fact",
          "tag": "Before",
          "text": "Pauses and captions eat the edit"
        },
        {
          "at_cue": 3,
          "key": "transcript",
          "role": "proof",
          "tag": "Now",
          "text": "The transcript drives every cut"
        },
        {
          "at_cue": 5,
          "key": "moment",
          "role": "number",
          "text": "moment re-renders",
          "value": 1
        },
        {
          "button": "mosio render",
          "key": "next",
          "role": "cta",
          "text": "Try it on your next video"
        }
      ]
    },
    "format": {
      "ratio": "9:16"
    },
    "media": {
      "footage": "../../fixtures/nm-talking-head/assets/th-footage.mp4",
      "music": "../../fixtures/nm-talking-head/assets/th-music.wav",
      "transcript": "../../fixtures/nm-talking-head/assets/th-transcript.srt"
    },
    "name": "talking-head-demo",
    "reframe": {
      "focus_x": 0.5
    },
    "style": {
      "brand": {
        "accent": "#f59e0b",
        "bg": "#111827",
        "main": "#38bdf8",
        "text": "#f9fafb",
        "text_on_accent": "#111827"
      },
      "pacing": "medium"
    }
  },
  "schema": {
    "additionalProperties": false,
    "properties": {
      "captions": {
        "additionalProperties": false,
        "default": {},
        "description": "Burned-in captions from the transcript.",
        "properties": {
          "enabled": {
            "default": true,
            "description": "Write captions/captions.srt and burn it in with the brand colours.",
            "type": "boolean"
          }
        },
        "type": "object"
      },
      "content": {
        "additionalProperties": false,
        "default": {},
        "description": "The overlays.",
        "properties": {
          "beats": {
            "description": "One overlay scene per beat, in order: an a-roll lower third first, a cta end card last, callouts and numbers in between, each starting at its transcript cue.",
            "items": {
              "additionalProperties": false,
              "allOf": [
                {
                  "if": {
                    "properties": {
                      "role": {
                        "const": "number"
                      }
                    }
                  },
                  "then": {
                    "required": [
                      "value"
                    ]
                  }
                }
              ],
              "properties": {
                "at_cue": {
                  "description": "Transcript cue (1-based, in the original transcript) the overlay starts with. Required for every beat but cta; ignored for the first beat, which starts at 0.",
                  "minimum": 1,
                  "type": "integer"
                },
                "button": {
                  "default": "",
                  "description": "cta: text of the pill under the line. Empty for none.",
                  "maxLength": 28,
                  "type": "string"
                },
                "decimals": {
                  "default": 0,
                  "description": "number: decimals shown while counting.",
                  "maximum": 3,
                  "minimum": 0,
                  "type": "integer"
                },
                "id": {
                  "description": "Optional scene id (used in every data-mosio-id). Defaults to the role name; a repeated role gets -2, -3.",
                  "pattern": "^[a-z][a-z0-9-]{0,23}$",
                  "type": "string"
                },
                "key": {
                  "description": "The word or words of the text to stress with the accent colour. Must occur in the text.",
                  "maxLength": 40,
                  "type": "string"
                },
                "role": {
                  "description": "a-roll: the speaker's lower third (first beat). fact, proof: a callout card. number: a counting stat. cta: the end card after the speech (last beat).",
                  "enum": [
                    "a-roll",
                    "fact",
                    "proof",
                    "number",
                    "cta"
                  ]
                },
                "subtitle": {
                  "description": "a-roll: second line of the lower third (role, company).",
                  "maxLength": 48,
                  "type": "string"
                },
                "suffix": {
                  "default": "",
                  "description": "number: text right after the value, e.g. % or x.",
                  "maxLength": 4,
                  "type": "string"
                },
                "tag": {
                  "default": "",
                  "description": "fact, proof: small label above the callout text. Empty for none.",
                  "maxLength": 16,
                  "type": "string"
                },
                "text": {
                  "description": "The words on screen, written literally into the scene HTML. For a-roll, the speaker's name.",
                  "maxLength": 60,
                  "minLength": 1,
                  "type": "string"
                },
                "value": {
                  "description": "number: the value the counter runs to.",
                  "type": "number"
                },
                "weight": {
                  "default": "medium",
                  "description": "Kept for the shared params shape; media recipes time beats by the transcript, not by weight.",
                  "enum": [
                    "short",
                    "medium",
                    "long"
                  ]
                }
              },
              "required": [
                "role",
                "text"
              ],
              "type": "object"
            },
            "maxItems": 8,
            "minItems": 2,
            "type": "array"
          }
        },
        "type": "object"
      },
      "cut": {
        "additionalProperties": false,
        "default": {},
        "description": "What is cut out of the footage.",
        "properties": {
          "keep": {
            "default": [],
            "description": "keep mode: source ranges in seconds, in any order.",
            "items": {
              "additionalProperties": false,
              "properties": {
                "in": {
                  "description": "Start, seconds into the footage.",
                  "minimum": 0,
                  "type": "number"
                },
                "out": {
                  "description": "End, seconds into the footage.",
                  "exclusiveMinimum": 0,
                  "type": "number"
                }
              },
              "required": [
                "in",
                "out"
              ],
              "type": "object"
            },
            "type": "array"
          },
          "merge_gap_s": {
            "default": 0.35,
            "description": "transcript mode: pauses shorter than this are kept (the cues are joined).",
            "maximum": 2,
            "minimum": 0,
            "type": "number"
          },
          "mode": {
            "default": "transcript",
            "description": "transcript: keep every cue (padded), cut the pauses between them. keep: keep only the given ranges.",
            "enum": [
              "transcript",
              "keep"
            ]
          },
          "pad_s": {
            "default": 0.12,
            "description": "transcript mode: seconds kept before and after each cue, so words are not clipped.",
            "maximum": 0.5,
            "minimum": 0,
            "type": "number"
          }
        },
        "type": "object"
      },
      "end_hold_s": {
        "default": 2.5,
        "description": "Length of the end card after the last word.",
        "maximum": 6,
        "minimum": 1,
        "type": "number"
      },
      "format": {
        "additionalProperties": false,
        "default": {},
        "description": "Output size. The length follows the cut transcript plus the end card.",
        "properties": {
          "ratio": {
            "default": "9:16",
            "description": "9:16 reframes landscape footage to vertical around reframe.focus_x; 16:9 keeps it landscape.",
            "enum": [
              "9:16",
              "16:9"
            ]
          }
        },
        "type": "object"
      },
      "media": {
        "additionalProperties": false,
        "description": "The source files, relative to the params file. They are copied into the project's assets/media/.",
        "properties": {
          "broll": {
            "default": [],
            "description": "Picture-only clips cut over the speaker while they keep talking.",
            "items": {
              "additionalProperties": false,
              "properties": {
                "at_cue": {
                  "description": "Transcript cue the clip covers; it starts 0.2 s into the cue.",
                  "minimum": 1,
                  "type": "integer"
                },
                "frames": {
                  "description": "Length in frames; defaults to the rest of the cue.",
                  "minimum": 15,
                  "type": "integer"
                },
                "id": {
                  "description": "Clip id in mosio.json. Defaults to broll-N.",
                  "pattern": "^[a-z][a-z0-9-]{0,23}$",
                  "type": "string"
                },
                "src": {
                  "description": "The B-roll file, relative to the params file.",
                  "minLength": 1,
                  "type": "string"
                }
              },
              "required": [
                "src",
                "at_cue"
              ],
              "type": "object"
            },
            "maxItems": 8,
            "type": "array"
          },
          "footage": {
            "description": "The speaker footage (any format Mosio decodes), with its own audio.",
            "minLength": 1,
            "type": "string"
          },
          "footage_size": {
            "additionalProperties": false,
            "default": {},
            "description": "Display size of the footage in pixels, for the reframe (the applier does not decode media).",
            "properties": {
              "height": {
                "default": 1080,
                "description": "Display height in pixels.",
                "minimum": 16,
                "type": "integer"
              },
              "width": {
                "default": 1920,
                "description": "Display width in pixels.",
                "minimum": 16,
                "type": "integer"
              }
            },
            "type": "object"
          },
          "music": {
            "description": "Optional music bed (any audio Mosio decodes), at least as long as the cut video.",
            "minLength": 1,
            "type": "string"
          },
          "transcript": {
            "description": "SubRip transcript of the footage, one cue per spoken line, timed to the footage. It drives the cuts and becomes the captions.",
            "pattern": "\\.srt$",
            "type": "string"
          }
        },
        "required": [
          "footage",
          "transcript"
        ],
        "type": "object"
      },
      "mix": {
        "additionalProperties": false,
        "default": {},
        "description": "Music level (the speech plays at 0 dB).",
        "properties": {
          "duck_frames": {
            "default": 12,
            "description": "Length of the equal-power crossfade between the two levels.",
            "maximum": 60,
            "minimum": 1,
            "type": "integer"
          },
          "music_db": {
            "default": -22,
            "description": "Music gain under the speech (ducked).",
            "maximum": 0,
            "minimum": -60,
            "type": "number"
          },
          "music_db_end": {
            "default": -10,
            "description": "Music gain under the end card.",
            "maximum": 0,
            "minimum": -60,
            "type": "number"
          }
        },
        "type": "object"
      },
      "name": {
        "default": "talking-head",
        "description": "Project name written to mosio.json.",
        "pattern": "^[a-z0-9][a-z0-9-]{1,39}$",
        "type": "string"
      },
      "reframe": {
        "additionalProperties": false,
        "default": {},
        "description": "How the footage fills the frame.",
        "properties": {
          "focus_x": {
            "default": 0.5,
            "description": "Horizontal position of the speaker in the footage (0 left, 1 right); 9:16 keeps it centred.",
            "maximum": 1,
            "minimum": 0,
            "type": "number"
          },
          "punch_in": {
            "default": 1.08,
            "description": "Zoom on every other cut, which hides the jump between two kept segments. 1 turns it off.",
            "maximum": 1.3,
            "minimum": 1,
            "type": "number"
          }
        },
        "type": "object"
      },
      "style": {
        "additionalProperties": false,
        "default": {},
        "description": "Look: brand colours, type size and motion speed.",
        "properties": {
          "brand": {
            "additionalProperties": false,
            "default": {},
            "description": "Brand colours. They are written to shared/tokens.css (overlays) and to the captions style in mosio.json.",
            "properties": {
              "accent": {
                "default": "#f59e0b",
                "description": "Key words, the lower-third bar, the stat and the button (--accent).",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "type": "string"
              },
              "bg": {
                "default": "#111827",
                "description": "Card and end-card background, caption outline (--bg).",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "type": "string"
              },
              "main": {
                "default": "#38bdf8",
                "description": "Tag pill and end-card glow (--main).",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "type": "string"
              },
              "text": {
                "default": "#f9fafb",
                "description": "Overlay and caption text (--text).",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "type": "string"
              },
              "text_on_accent": {
                "default": "#111827",
                "description": "Text on the accent colour, the button label (--text-on-accent).",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "type": "string"
              }
            },
            "type": "object"
          },
          "font_scale": {
            "default": 1,
            "description": "Multiplier on every overlay and caption size (--type-scale).",
            "maximum": 1.25,
            "minimum": 0.6,
            "type": "number"
          },
          "pacing": {
            "default": "medium",
            "description": "Speed of the overlay entrances (--pace).",
            "enum": [
              "calm",
              "medium",
              "brisk"
            ]
          }
        },
        "type": "object"
      }
    },
    "required": [
      "media"
    ],
    "type": "object"
  }
}

{
  "schema": "mosio.recipe/1",
  "id": "talking-head",
  "title": "Talking head",
  "description": "A speaker video edited from its transcript: pauses cut, landscape footage reframed to vertical, captions, a lower third, callouts and stats, B-roll and a ducked music bed, then an end card.",
  "version": "0.1.0",
  "tags": [
    "talking-head",
    "footage",
    "captions",
    "social"
  ],
  "license": "MIT",
  "provenance": {
    "authors": [
      "Mosio"
    ],
    "sources": [
      {
        "kind": "own",
        "name": "fixtures/nm-hybrid-demo",
        "path": "fixtures/nm-hybrid-demo",
        "what": "GSAP overlays over native footage with libass captions; re-authored as transcript-timed overlays"
      }
    ]
  },
  "formats": [
    {
      "ratio": "9:16",
      "width": 1080,
      "height": 1920,
      "fps": 30,
      "vars": {
        "fs_name": 64,
        "fs_sub": 36,
        "fs_callout": 76,
        "fs_number": 200,
        "fs_end": 96,
        "margin": 72,
        "lower_bottom": 560,
        "callout_top": 110,
        "cap_size": 58,
        "cap_margin": 300
      }
    },
    {
      "ratio": "16:9",
      "width": 1920,
      "height": 1080,
      "fps": 30,
      "vars": {
        "fs_name": 56,
        "fs_sub": 30,
        "fs_callout": 62,
        "fs_number": 170,
        "fs_end": 88,
        "margin": 96,
        "lower_bottom": 200,
        "callout_top": 110,
        "cap_size": 48,
        "cap_margin": 80
      }
    }
  ],
  "duration_s": {
    "min": 6,
    "default": 20,
    "max": 180
  },
  "beats": {
    "roles": [
      "a-roll",
      "fact",
      "proof",
      "number",
      "cta"
    ],
    "min": 2,
    "max": 8,
    "tempo_s": {
      "short": 2,
      "medium": 3,
      "long": 4
    },
    "ending_min_s": 1.5
  },
  "plan": [
    {
      "roles": [
        "a-roll"
      ],
      "scene": "scenes/lower-third.html",
      "technique": "accent bar grows, card wipes in, name words rise, subtitle fades; leaves after ~4 s",
      "primitives": [
        "bar-grow",
        "wipe-in",
        "rise-fade"
      ],
      "limits": {
        "max_words": 4
      }
    },
    {
      "roles": [
        "fact",
        "proof"
      ],
      "scene": "scenes/callout.html",
      "technique": "card pops in near the top, tag slides, words rise one by one, underline draws",
      "primitives": [
        "pop",
        "rise-fade",
        "draw"
      ],
      "limits": {
        "max_words": 9
      }
    },
    {
      "roles": [
        "number"
      ],
      "scene": "scenes/number.html",
      "technique": "card pops, value counts up from zero, label words rise",
      "primitives": [
        "pop",
        "count-up",
        "rise-fade"
      ],
      "limits": {
        "max_words": 6
      }
    },
    {
      "roles": [
        "cta"
      ],
      "scene": "scenes/end-card.html",
      "technique": "brand end card fades over the last frame, words rise, button pops",
      "primitives": [
        "fade",
        "rise-fade",
        "pop"
      ],
      "limits": {
        "max_words": 6
      }
    }
  ],
  "controls": [
    {
      "param": "/reframe/focus_x",
      "label": "Speaker position",
      "effect": "Where the 9:16 crop sits on the landscape footage: transform.x of every a-roll clip in mosio.json."
    },
    {
      "param": "/cut/pad_s",
      "label": "Cut tightness",
      "effect": "How much air is kept around each line: the a-roll clip ranges, caption times and overlay starts all move, so most windows re-render."
    },
    {
      "param": "/style/brand/accent",
      "label": "Accent colour",
      "effect": "Key words, bar, stat and button: --accent in shared/tokens.css, so every overlay re-renders."
    },
    {
      "param": "/content/beats/1/text",
      "label": "Callout text",
      "effect": "Edit the words of one callout directly in its scene file; only that callout's windows re-render."
    }
  ],
  "inputs": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "media"
    ],
    "properties": {
      "name": {
        "type": "string",
        "pattern": "^[a-z0-9][a-z0-9-]{1,39}$",
        "default": "talking-head",
        "description": "Project name written to mosio.json."
      },
      "format": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "Output size. The length follows the cut transcript plus the end card.",
        "properties": {
          "ratio": {
            "enum": [
              "9:16",
              "16:9"
            ],
            "default": "9:16",
            "description": "9:16 reframes landscape footage to vertical around reframe.focus_x; 16:9 keeps it landscape."
          }
        }
      },
      "media": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "footage",
          "transcript"
        ],
        "description": "The source files, relative to the params file. They are copied into the project's assets/media/.",
        "properties": {
          "footage": {
            "type": "string",
            "minLength": 1,
            "description": "The speaker footage (any format Mosio decodes), with its own audio."
          },
          "footage_size": {
            "type": "object",
            "additionalProperties": false,
            "default": {},
            "description": "Display size of the footage in pixels, for the reframe (the applier does not decode media).",
            "properties": {
              "width": {
                "type": "integer",
                "minimum": 16,
                "default": 1920,
                "description": "Display width in pixels."
              },
              "height": {
                "type": "integer",
                "minimum": 16,
                "default": 1080,
                "description": "Display height in pixels."
              }
            }
          },
          "transcript": {
            "type": "string",
            "pattern": "\\.srt$",
            "description": "SubRip transcript of the footage, one cue per spoken line, timed to the footage. It drives the cuts and becomes the captions."
          },
          "music": {
            "type": "string",
            "minLength": 1,
            "description": "Optional music bed (any audio Mosio decodes), at least as long as the cut video."
          },
          "broll": {
            "type": "array",
            "maxItems": 8,
            "default": [],
            "description": "Picture-only clips cut over the speaker while they keep talking.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "src",
                "at_cue"
              ],
              "properties": {
                "id": {
                  "type": "string",
                  "pattern": "^[a-z][a-z0-9-]{0,23}$",
                  "description": "Clip id in mosio.json. Defaults to broll-N."
                },
                "src": {
                  "type": "string",
                  "minLength": 1,
                  "description": "The B-roll file, relative to the params file."
                },
                "at_cue": {
                  "type": "integer",
                  "minimum": 1,
                  "description": "Transcript cue the clip covers; it starts 0.2 s into the cue."
                },
                "frames": {
                  "type": "integer",
                  "minimum": 15,
                  "description": "Length in frames; defaults to the rest of the cue."
                }
              }
            }
          }
        }
      },
      "cut": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "What is cut out of the footage.",
        "properties": {
          "mode": {
            "enum": [
              "transcript",
              "keep"
            ],
            "default": "transcript",
            "description": "transcript: keep every cue (padded), cut the pauses between them. keep: keep only the given ranges."
          },
          "pad_s": {
            "type": "number",
            "minimum": 0,
            "maximum": 0.5,
            "default": 0.12,
            "description": "transcript mode: seconds kept before and after each cue, so words are not clipped."
          },
          "merge_gap_s": {
            "type": "number",
            "minimum": 0,
            "maximum": 2,
            "default": 0.35,
            "description": "transcript mode: pauses shorter than this are kept (the cues are joined)."
          },
          "keep": {
            "type": "array",
            "default": [],
            "description": "keep mode: source ranges in seconds, in any order.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "in",
                "out"
              ],
              "properties": {
                "in": {
                  "type": "number",
                  "minimum": 0,
                  "description": "Start, seconds into the footage."
                },
                "out": {
                  "type": "number",
                  "exclusiveMinimum": 0,
                  "description": "End, seconds into the footage."
                }
              }
            }
          }
        }
      },
      "reframe": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "How the footage fills the frame.",
        "properties": {
          "focus_x": {
            "type": "number",
            "minimum": 0,
            "maximum": 1,
            "default": 0.5,
            "description": "Horizontal position of the speaker in the footage (0 left, 1 right); 9:16 keeps it centred."
          },
          "punch_in": {
            "type": "number",
            "minimum": 1,
            "maximum": 1.3,
            "default": 1.08,
            "description": "Zoom on every other cut, which hides the jump between two kept segments. 1 turns it off."
          }
        }
      },
      "mix": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "Music level (the speech plays at 0 dB).",
        "properties": {
          "music_db": {
            "type": "number",
            "minimum": -60,
            "maximum": 0,
            "default": -22,
            "description": "Music gain under the speech (ducked)."
          },
          "music_db_end": {
            "type": "number",
            "minimum": -60,
            "maximum": 0,
            "default": -10,
            "description": "Music gain under the end card."
          },
          "duck_frames": {
            "type": "integer",
            "minimum": 1,
            "maximum": 60,
            "default": 12,
            "description": "Length of the equal-power crossfade between the two levels."
          }
        }
      },
      "captions": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "Burned-in captions from the transcript.",
        "properties": {
          "enabled": {
            "type": "boolean",
            "default": true,
            "description": "Write captions/captions.srt and burn it in with the brand colours."
          }
        }
      },
      "end_hold_s": {
        "type": "number",
        "minimum": 1,
        "maximum": 6,
        "default": 2.5,
        "description": "Length of the end card after the last word."
      },
      "content": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "The overlays.",
        "properties": {
          "beats": {
            "type": "array",
            "minItems": 2,
            "maxItems": 8,
            "description": "One overlay scene per beat, in order: an a-roll lower third first, a cta end card last, callouts and numbers in between, each starting at its transcript cue.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "role",
                "text"
              ],
              "properties": {
                "id": {
                  "type": "string",
                  "pattern": "^[a-z][a-z0-9-]{0,23}$",
                  "description": "Optional scene id (used in every data-mosio-id). Defaults to the role name; a repeated role gets -2, -3."
                },
                "role": {
                  "enum": [
                    "a-roll",
                    "fact",
                    "proof",
                    "number",
                    "cta"
                  ],
                  "description": "a-roll: the speaker's lower third (first beat). fact, proof: a callout card. number: a counting stat. cta: the end card after the speech (last beat)."
                },
                "text": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 60,
                  "description": "The words on screen, written literally into the scene HTML. For a-roll, the speaker's name."
                },
                "key": {
                  "type": "string",
                  "maxLength": 40,
                  "description": "The word or words of the text to stress with the accent colour. Must occur in the text."
                },
                "at_cue": {
                  "type": "integer",
                  "minimum": 1,
                  "description": "Transcript cue (1-based, in the original transcript) the overlay starts with. Required for every beat but cta; ignored for the first beat, which starts at 0."
                },
                "subtitle": {
                  "type": "string",
                  "maxLength": 48,
                  "description": "a-roll: second line of the lower third (role, company)."
                },
                "tag": {
                  "type": "string",
                  "maxLength": 16,
                  "default": "",
                  "description": "fact, proof: small label above the callout text. Empty for none."
                },
                "value": {
                  "type": "number",
                  "description": "number: the value the counter runs to."
                },
                "decimals": {
                  "type": "integer",
                  "minimum": 0,
                  "maximum": 3,
                  "default": 0,
                  "description": "number: decimals shown while counting."
                },
                "suffix": {
                  "type": "string",
                  "maxLength": 4,
                  "default": "",
                  "description": "number: text right after the value, e.g. % or x."
                },
                "button": {
                  "type": "string",
                  "maxLength": 28,
                  "default": "",
                  "description": "cta: text of the pill under the line. Empty for none."
                },
                "weight": {
                  "enum": [
                    "short",
                    "medium",
                    "long"
                  ],
                  "default": "medium",
                  "description": "Kept for the shared params shape; media recipes time beats by the transcript, not by weight."
                }
              },
              "allOf": [
                {
                  "if": {
                    "properties": {
                      "role": {
                        "const": "number"
                      }
                    }
                  },
                  "then": {
                    "required": [
                      "value"
                    ]
                  }
                }
              ]
            }
          }
        }
      },
      "style": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "Look: brand colours, type size and motion speed.",
        "properties": {
          "brand": {
            "type": "object",
            "additionalProperties": false,
            "default": {},
            "description": "Brand colours. They are written to shared/tokens.css (overlays) and to the captions style in mosio.json.",
            "properties": {
              "bg": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Card and end-card background, caption outline (--bg).",
                "default": "#111827"
              },
              "main": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Tag pill and end-card glow (--main).",
                "default": "#38bdf8"
              },
              "accent": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Key words, the lower-third bar, the stat and the button (--accent).",
                "default": "#f59e0b"
              },
              "text": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Overlay and caption text (--text).",
                "default": "#f9fafb"
              },
              "text_on_accent": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Text on the accent colour, the button label (--text-on-accent).",
                "default": "#111827"
              }
            }
          },
          "font_scale": {
            "type": "number",
            "minimum": 0.6,
            "maximum": 1.25,
            "default": 1,
            "description": "Multiplier on every overlay and caption size (--type-scale)."
          },
          "pacing": {
            "enum": [
              "calm",
              "medium",
              "brisk"
            ],
            "default": "medium",
            "description": "Speed of the overlay entrances (--pace)."
          }
        }
      }
    }
  },
  "files": {
    "scenes": [
      "scenes/lower-third.html",
      "scenes/callout.html",
      "scenes/number.html",
      "scenes/end-card.html"
    ],
    "shared": [
      "shared/tokens.css",
      "shared/base.css"
    ],
    "fonts": [
      "Inter-Regular.otf",
      "Inter-Bold.otf",
      "Inter-ExtraBold.otf"
    ]
  },
  "example": {
    "project": "example/",
    "params": "example.params.json"
  },
  "engine": {
    "libraries": [
      "gsap@3.15.1"
    ]
  },
  "requires": [],
  "media": {
    "timeline": "a-roll/1"
  },
  "derive": [
    {
      "as": "pace",
      "from": "/style/pacing",
      "map": {
        "calm": 1.3,
        "medium": 1,
        "brisk": 0.75
      }
    }
  ]
}

/* Fixed foundation of the recipe: fonts, reset and the scene frame. Overlays are transparent: the footage shows
   through everywhere they do not draw. Brand values are in tokens.css, not here. */
@font-face { font-family: "Inter"; font-weight: 400; src: url("/assets/fonts/Inter-Regular.otf") format("opentype"); }
@font-face { font-family: "Inter"; font-weight: 700; src: url("/assets/fonts/Inter-Bold.otf") format("opentype"); }
@font-face { font-family: "Inter"; font-weight: 800; src: url("/assets/fonts/Inter-ExtraBold.otf") format("opentype"); }
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { width: var(--w); height: var(--h); overflow: hidden; background: transparent; color: var(--text); font-family: var(--font-body); }
.scene { position: absolute; inset: 0; overflow: hidden; }
.w { display: inline-block; white-space: nowrap; }
.acc { color: var(--accent); }

/* Brand and layout tokens for every overlay (recipe talking-head). Edit values here: every scene that imports this
   file re-renders, which is correct, because they all depend on it. Captions take their colours from mosio.json. */
:root {
  --bg: {{brand.bg}};
  --main: {{brand.main}};
  --accent: {{brand.accent}};
  --text: {{brand.text}};
  --text-on-accent: {{brand.text_on_accent}};
  --card: color-mix(in srgb, var(--bg) 86%, transparent);
  --text-dim: color-mix(in srgb, var(--text) 72%, var(--bg));
  --font-display: "Inter", sans-serif;
  --font-body: "Inter", sans-serif;
  --w: {{format.width}}px;
  --h: {{format.height}}px;
  --type-scale: {{style.font_scale}};
  --pace: {{derived.pace}};
  --fs-name: {{format.vars.fs_name}}px;
  --fs-sub: {{format.vars.fs_sub}}px;
  --fs-callout: {{format.vars.fs_callout}}px;
  --fs-number: {{format.vars.fs_number}}px;
  --fs-end: {{format.vars.fs_end}}px;
  --margin: {{format.vars.margin}}px;
  --lower-bottom: {{format.vars.lower_bottom}}px;
  --callout-top: {{format.vars.callout_top}}px;
}
